using System.IO;
using System.IO.Compression;
using System.Net;
using System.Net.Http;
using System.Security;
using System.Security.Cryptography;
using System.Text.Json;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Threading;
using RenoDXMfgUnlocker;
using RenoDX.Publisher;

internal static class Rc6Checks
{
    internal static IEnumerable<(string Name,Action Run)> All() {
        yield return("rc6 progress is hidden when idle checking cancelled or complete and visible while downloading",Progress);
        yield return("rc6 production signing and accepted handoff are independent gates",TrustGate);
        yield return("rc6 encrypted test key roundtrip verifies signature and refuses wrong password",EncryptedKey);
        yield return("rc6 owner procedure rejects source and existing stores without generating credentials",OwnerGuards);
        yield return("rc6 acceptance message has six-language resource parity",Localization);
        yield return("rc6 stale cleanup removes only aged updater temporary files and preserves recovery",StaleCleanup);
    }
    private static void Check(bool value,string message){if(!value)throw new Exception(message);}
    private static string Temp(){var path=Path.Combine(Path.GetTempPath(),"RenoDX-RC6",Guid.NewGuid().ToString("N"));Directory.CreateDirectory(path);return path;}
    private sealed class Transport(string metadata,byte[] bytes):HttpMessageHandler {
        internal bool AssetRequested;internal bool Delay=true;
        protected override Task<HttpResponseMessage> SendAsync(HttpRequestMessage request,CancellationToken token){if(request.RequestUri!.Host=="api.github.com")return Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new StringContent(metadata)});AssetRequested=true;return Delay?Wait(token):Task.FromResult(new HttpResponseMessage(HttpStatusCode.OK){Content=new ByteArrayContent(bytes)});}
        private static async Task<HttpResponseMessage> Wait(CancellationToken token){await Task.Delay(-1,token);throw new Exception("Unreachable");}
    }
    private static void Pump(Task task){var clock=System.Diagnostics.Stopwatch.StartNew();while(!task.IsCompleted&&clock.Elapsed<TimeSpan.FromSeconds(6)){Dispatcher.CurrentDispatcher.Invoke(()=>{},DispatcherPriority.Background);Thread.Sleep(1);}Check(task.IsCompleted,"Unshown task timeout");task.GetAwaiter().GetResult();}
    private static void Progress()=>WpfCheckHost.Run(()=>{
        using var memory=new MemoryStream();using(var zip=new ZipArchive(memory,ZipArchiveMode.Create,true)){using var writer=new StreamWriter(zip.CreateEntry(SelfUpdateVerifier.Executable).Open());writer.Write("inert test data");}var bytes=memory.ToArray();
        var asset="RenoDX_MFG_Unlocker_v1.3.0_Windows_x64.zip";var json=JsonSerializer.Serialize(new[]{new{id=1,url=ApplicationUpdateService.ApiRoot+"/releases/1",html_url=ApplicationUpdateService.WebRoot+"/releases/tag/v1.3.0",tag_name="v1.3.0",name="Test",body="Notes",published_at="2026-11-02T00:00:00Z",draft=false,prerelease=false,assets=new[]{new{id=2,url=ApplicationUpdateService.ApiRoot+"/releases/assets/2",name=asset,state="uploaded",size=bytes.Length,digest="sha256:"+Convert.ToHexString(SHA256.HashData(bytes)).ToLowerInvariant(),browser_download_url=ApplicationUpdateService.WebRoot+"/releases/download/v1.3.0/"+asset}}}});
        var transport=new Transport(json,bytes);using var http=new HttpClient(transport);using var service=new ApplicationUpdateService(http);using var view=new ApplicationUpdateView(service,"1.2.0-rc.6",Temp(),_=>{},_=>{});
        Check(view.Progress.Visibility==Visibility.Collapsed,"Idle white strip remains");Pump(view.CheckAsync());Check(view.Progress.Visibility==Visibility.Collapsed,"Check/no transfer shows progress");
        var transfer=view.DownloadAsync();Check(transport.AssetRequested&&view.Progress.Visibility==Visibility.Visible&&view.CancelButton.IsEnabled,"Download progress/cancellation missing");view.CancelButton.RaiseEvent(new RoutedEventArgs(Button.ClickEvent));Pump(transfer);Check(view.Progress.Visibility==Visibility.Collapsed&&!view.Busy,"Cancellation did not hide progress");
        transport.Delay=false;Pump(view.DownloadAsync());Check(view.Progress.Visibility==Visibility.Collapsed&&view.FolderButton.IsEnabled&&!view.Busy,"Completed transfer did not hide progress");
    });
    private static void TrustGate(){Check(SelfUpdateTrust.HelperAcceptanceVerified,"Real-process acceptance gate not recorded");Check(SelfUpdateTrust.Configured&&SelfUpdateTrust.AutomaticReady&&SelfUpdateTrust.Keys.Count==1&&SelfUpdateTrust.Keys.ContainsKey("owner-release-2026"),"Production readiness or approved trust incorrect");Check(!typeof(MainWindow).Assembly.GetManifestResourceNames().Any(n=>n.StartsWith("SelfUpdateE2EFixture.",StringComparison.Ordinal)),"Fixture trust/root resource leaked into production assembly");if(SelfUpdateTrust.Keys is IDictionary<string,string> mutable){try{mutable.Add("not-approved","not-a-key");throw new Exception("Trust catalog mutable");}catch(NotSupportedException){}}Check(SelfUpdateHandoff.RunWorkerAsync(["--self-update-helper","invalid","1","0"]).GetAwaiter().GetResult()==78,"Production CLI bypassed owner key");}
    private static SecureString Password(string text){var secure=new SecureString();foreach(var c in text)secure.AppendChar(c);secure.MakeReadOnly();return secure;}
    private static void EncryptedKey(){using var password=Password("Test-only password, never a production credential.");var material=OwnerReleaseKeyCrypto.Create(password);Check(material.EncryptedPrivatePem.StartsWith("-----BEGIN ENCRYPTED PRIVATE KEY-----")&&!material.EncryptedPrivatePem.Contains("-----BEGIN PRIVATE KEY-----"),"Unencrypted private export");using var unlocked=OwnerReleaseKeyCrypto.Unlock(material.EncryptedPrivatePem,password);Check(Convert.ToBase64String(unlocked.ExportSubjectPublicKeyInfo())==material.PublicSpki&&Convert.ToHexString(SHA256.HashData(unlocked.ExportSubjectPublicKeyInfo()))==material.Fingerprint,"Backup/public identity mismatch");var challenge=RandomNumberGenerator.GetBytes(32);var signature=unlocked.SignData(challenge,HashAlgorithmName.SHA256,RSASignaturePadding.Pss);using var publicKey=RSA.Create();publicKey.ImportSubjectPublicKeyInfo(Convert.FromBase64String(material.PublicSpki),out _);Check(publicKey.VerifyData(challenge,signature,HashAlgorithmName.SHA256,RSASignaturePadding.Pss),"Encrypted-key signing failed");using var wrong=Password("Wrong test-only passphrase, not production.");try{using var rejected=OwnerReleaseKeyCrypto.Unlock(material.EncryptedPrivatePem,wrong);throw new Exception("Wrong password accepted");}catch(CryptographicException){}Check(SelfUpdateTrust.Keys.Count==1&&SelfUpdateTrust.Keys["owner-release-2026"]!=material.PublicSpki,"Encrypted test key became production trust");}
    private static void OwnerGuards(){var source=Path.GetFullPath(Path.Combine(AppContext.BaseDirectory,"../../../../.."));var script=Path.Combine(source,"tools","New-OwnerReleaseKey.ps1");var existing=Temp();File.WriteAllText(Path.Combine(existing,"keep.txt"),"preserve");foreach(var destination in new[]{Path.Combine(source,"forbidden-production-key"),existing}){var start=new System.Diagnostics.ProcessStartInfo("pwsh"){UseShellExecute=false,CreateNoWindow=true,RedirectStandardInput=true,RedirectStandardOutput=true,RedirectStandardError=true};foreach(var arg in new[]{"-NoProfile","-File",script,"-StoreDirectory",destination,"-KeyId","never-generated"})start.ArgumentList.Add(arg);using var process=System.Diagnostics.Process.Start(start)!;process.StandardInput.Close();var output=process.StandardOutput.ReadToEndAsync();var errors=process.StandardError.ReadToEndAsync();if(!process.WaitForExit(10000)){process.Kill(true);throw new Exception("Owner guard unexpectedly prompted/hung");}Check(process.ExitCode!=0&&!output.GetAwaiter().GetResult().Contains("PUBLIC SPKI:"),"Unapproved production key generation occurred");var error=errors.GetAwaiter().GetResult();Check(error.Contains(destination==existing?"existing key stores":"Private keys must stay outside"),"Wrong owner guard refusal");}Check(File.ReadAllText(Path.Combine(existing,"keep.txt"))=="preserve"&&!Directory.Exists(Path.Combine(source,"forbidden-production-key")),"Owner guard changed files");}
    private static void Localization(){var language=new UiLocalization();Check(language.ValidateCatalogs().Count==0,"Catalog integrity");const string key="Automatic installation is disabled until helper acceptance tests are complete. Use manual download.";foreach(var culture in UiLocalization.Cultures)Check(language.GetCatalog(culture).ContainsKey(key)&&(culture=="en-US"||language.Lookup(key,culture)!=key),"RC6 untranslated: "+culture);}
    private static void StaleCleanup(){var root=Temp();var stale=Path.Combine(root,Guid.NewGuid().ToString("N"));var recent=Path.Combine(root,Guid.NewGuid().ToString("N"));foreach(var folder in new[]{stale,recent}){Directory.CreateDirectory(folder);foreach(var name in new[]{"package.zip","payload.exe","worker.exe","original.exe","operation.json","unrelated.txt"})File.WriteAllText(Path.Combine(folder,name),"inert keep/remove fixture");}Directory.SetLastWriteTimeUtc(stale,DateTime.UtcNow.AddDays(-2));SelfUpdatePaths.CleanupStaleSessions(root);Check(!File.Exists(Path.Combine(stale,"worker.exe"))&&!File.Exists(Path.Combine(stale,"package.zip"))&&!File.Exists(Path.Combine(stale,"payload.exe")),"Aged updater temporary files remain");Check(File.Exists(Path.Combine(stale,"original.exe"))&&File.Exists(Path.Combine(stale,"operation.json"))&&File.Exists(Path.Combine(stale,"unrelated.txt")),"Recovery or unrelated file was removed");Check(File.Exists(Path.Combine(recent,"worker.exe")),"Active/recent session was pruned");}
}
